const OUTPUT_LABELS = { paper: { en: "Paper", ar: "ورقة بحثية" }, dataset: { en: "Dataset", ar: "مجموعة بيانات" }, corpus: { en: "Corpus", ar: "مدونة" }, benchmark: { en: "Benchmark", ar: "معيار" }, prototype: { en: "Prototype", ar: "نموذج أولي" } };
const localized = (value, language) => value?.[language] ?? value?.en ?? value;

export default function Projects() {
  const { language } = useLanguage();
  const locale = language === "ar" ? "ar" : "en";
  const copy = COPY[locale];
  const [guidePath, setGuidePath] = useState("corpus-linguistics");
  const [challengeId, setChallengeId] = useState("dialects");
  const [socialFilters, setSocialFilters] = useState({ domain: "", form: "", team: "", annotation: "", complexity: "" });
  const [appliedFilters, setAppliedFilters] = useState({ sector: "", form: "", team: "", annotation: "", complexity: "" });
  const [answers, setAnswers] = useState({ path: "", challenge: "", challengeFocus: "", socialDomain: "", socialNeed: "", appliedSector: "", appliedNeed: "", goal: "", data: "", dataType: "", reference: "", team: "", annotation: "", task: "", complexity: "" });
  const [filters, setFilters] = useState({ path: "", challenge: "", team: "", annotation: "", complexity: "", output: "" });
  const [selectedId, setSelectedId] = useState("");
  const guide = PATH_GUIDANCE[guidePath];
  const recommendations = useMemo(() => recommendProjects(answers), [answers]);
  const filtered = useMemo(() => PROJECT_CATALOG.filter((item) => (!filters.path || item.path === filters.path) && (!filters.challenge || item.challengeId === filters.challenge || item.challengeIds?.includes(filters.challenge) || CHALLENGE_BY_ID[filters.challenge]?.possibleProjects.includes(item.id)) && (!filters.team || item.teamType === filters.team) && (!filters.annotation || (filters.annotation === "yes") === item.annotatorsRequired) && (!filters.complexity || item.complexity === filters.complexity) && (!filters.output || item.possibleOutputs.includes(filters.output))), [filters]);
  const selected = PROJECT_CATALOG.find((item) => item.id === selectedId);
  const setter = (stateSetter, key) => (event) => stateSetter((current) => ({ ...current, [key]: event.target.value }));
  if (selected) return <ProjectDetail project={selected} language={locale} copy={copy} onBack={() => setSelectedId("")} />;

  return <main className={styles.page}>
    <Head><title>{copy.pageTitle}</title></Head>
    <nav className={styles.nav} aria-label={locale === "ar" ? "التنقل الرئيسي" : "Primary navigation"}><Link href="/" className={styles.brand}><span className={styles.brandMark}>L</span><span>LinguaLab</span></Link><div className={styles.navLinks}><Link href="/">{copy.home}</Link><Link href="/ar-tools">{copy.research}</Link><Link href="/projects" aria-current="page">{copy.projects}</Link></div></nav>
    <header className={styles.hero}><p className={styles.eyebrow}>{copy.eyebrow}</p><h1>{copy.title}</h1><p className={styles.lead}>{copy.lead}</p><ol className={styles.journey}>{copy.journey.map((step, index) => <li key={step}><span>{index + 1}</span>{step}</li>)}</ol></header>

    <section className={styles.section} aria-labelledby="path-guidance-title"><SectionHeading number="01" title={copy.guidanceTitle} lead={copy.guidanceLead} id="path-guidance-title" /><div className={styles.pathTabs} role="tablist" aria-label={copy.guidanceTitle}>{Object.entries(PATH_GUIDANCE).map(([id, item]) => <button key={id} type="button" role="tab" aria-selected={guidePath === id} onClick={() => setGuidePath(id)}>{localized(item.name, locale)}</button>)}</div><article className={styles.guideCard}><h3>{localized(guide.name, locale)}</h3><div className={styles.guideGrid}>{[[copy.problem, guide.problem], [copy.questions, guide.questions], [copy.data, guide.data], [copy.annotation, guide.annotation], [copy.outputs, guide.outputs], [copy.evaluation, guide.evaluation], [copy.beginner, guide.beginner]].map(([label, value]) => <Info key={label} title={label} text={localized(value, locale)} />)}<div><h4>{copy.tools}</h4><div className={styles.badges}>{guide.tools.map((tool) => <span key={tool}>{tool}</span>)}</div></div></div></article></section>

    <ChallengeExplorer activeId={challengeId} onSelect={setChallengeId} language={locale} copy={copy} onOpenProject={setSelectedId} />

    <SocialImpactExplorer filters={socialFilters} onFilter={setter(setSocialFilters)} language={locale} copy={copy} onOpenProject={setSelectedId} />

    <AppliedProjectExplorer filters={appliedFilters} onFilter={setter(setAppliedFilters)} language={locale} copy={copy} onOpenProject={setSelectedId} />

    <section className={`${styles.section} ${styles.finder}`} aria-labelledby="finder-title"><SectionHeading number="05" title={copy.finderTitle} lead={copy.finderLead} id="finder-title" /><div className={styles.questionGrid}>
      <Select label={copy.pathQ} value={answers.path} onChange={setter(setAnswers, "path")} options={Object.entries(PATH_GUIDANCE).map(([value, item]) => [value, localized(item.name, locale)])} copy={copy} />
      <Select label={copy.challengeQ} value={answers.challenge} onChange={setter(setAnswers, "challenge")} options={ARABIC_CHALLENGE_FAMILIES.map((item) => [item.id, locale === "ar" ? item.titleAr : item.titleEn])} copy={copy} />
      <Select label={copy.focusQ} value={answers.challengeFocus} onChange={setter(setAnswers, "challengeFocus")} options={[["ambiguity", copy.ambiguity], ["variation", copy.variation], ["quality", copy.quality], ["speech", copy.speech], ["classification", copy.classify], ["evaluation", copy.evaluationTask]]} copy={copy} />
      <Select label={copy.socialDomain} value={answers.socialDomain} onChange={setter(setAnswers, "socialDomain")} options={SOCIAL_IMPACT_DOMAINS.map((item) => [item.id, locale === "ar" ? item.titleAr : item.titleEn])} copy={copy} />
      <Select label={copy.socialNeed} value={answers.socialNeed} onChange={setter(setAnswers, "socialNeed")} options={[["instructions", copy.instructionsNeed], ["ambiguity", copy.ambiguity], ["semantic-matching", copy.matchingNeed], ["pragmatics", copy.pragmaticsNeed], ["simplification", copy.accessibilityNeed], ["evaluation", copy.evaluationTask]]} copy={copy} />
      <Select label={copy.sector} value={answers.appliedSector} onChange={setter(setAnswers, "appliedSector")} options={APPLIED_SECTORS.map((item) => [item.id, locale === "ar" ? item.titleAr : item.titleEn])} copy={copy} />
      <Select label={copy.appliedNeed} value={answers.appliedNeed} onChange={setter(setAnswers, "appliedNeed")} options={[["instructions", copy.instructionsNeed], ["ambiguity", copy.ambiguity], ["extraction", copy.terminologyNeed], ["semantic-matching", copy.matchingNeed], ["pragmatics", copy.pragmaticsNeed], ["topic", copy.comparisonNeed], ["evaluation", copy.evaluationTask]]} copy={copy} />
      <Select label={copy.goalQ} value={answers.goal} onChange={setter(setAnswers, "goal")} options={[["paper", copy.paper], ["dataset", copy.dataset], ["benchmark", copy.benchmark], ["prototype", copy.prototype]]} copy={copy} />
      <Select label={copy.dataQ} value={answers.data} onChange={setter(setAnswers, "data")} options={[["yes", copy.yes], ["no", copy.no]]} copy={copy} />
      <Select label={copy.dataTypeQ} value={answers.dataType} onChange={setter(setAnswers, "dataType")} options={[["texts", copy.texts], ["labeled", copy.labeled], ["terms", copy.terms], ["experimental", copy.experimental]]} copy={copy} />
      <Select label={copy.referenceQ} value={answers.reference} onChange={setter(setAnswers, "reference")} options={[["yes", copy.yes], ["no", copy.no]]} copy={copy} />
      <Select label={copy.teamQ} value={answers.team} onChange={setter(setAnswers, "team")} options={[["individual", copy.individual], ["team", copy.team]]} copy={copy} />
      <Select label={copy.annotationQ} value={answers.annotation} onChange={setter(setAnswers, "annotation")} options={[["yes", copy.yes], ["no", copy.no]]} copy={copy} />
      <Select label={copy.taskQ} value={answers.task} onChange={setter(setAnswers, "task")} options={[["corpus", copy.describe], ["classification", copy.classify], ["extraction", copy.extraction], ["evaluation", copy.evaluationTask], ["experiment", copy.experiment]]} copy={copy} />
      <Select label={copy.complexityQ} value={answers.complexity} onChange={setter(setAnswers, "complexity")} options={[["beginner", copy.beginnerLevel], ["intermediate", copy.intermediate], ["advanced", copy.advanced]]} copy={copy} />
    </div><div className={styles.recommendations}><h3>{copy.recommendations}</h3><div className={styles.compactGrid}>{recommendations.map((item) => <ProjectCard key={item.id} project={item} locale={locale} copy={copy} onOpen={setSelectedId} compact />)}</div></div></section>

    <section className={styles.section} aria-labelledby="catalog-title"><SectionHeading number="06" title={copy.catalog} lead={copy.catalogLead} id="catalog-title" /><div className={styles.filters} aria-label={copy.filters}>
      <Select label={copy.pathQ} value={filters.path} onChange={setter(setFilters, "path")} options={Object.entries(PATH_GUIDANCE).map(([value, item]) => [value, localized(item.name, locale)])} copy={copy} />
      <Select label={copy.challengeQ} value={filters.challenge} onChange={setter(setFilters, "challenge")} options={ARABIC_CHALLENGE_FAMILIES.map((item) => [item.id, locale === "ar" ? item.titleAr : item.titleEn])} copy={copy} />
      <Select label={copy.teamLabel} value={filters.team} onChange={setter(setFilters, "team")} options={[["individual", copy.individual], ["team", copy.team]]} copy={copy} />
      <Select label={copy.annotationLabel} value={filters.annotation} onChange={setter(setFilters, "annotation")} options={[["yes", copy.needsAnnotation], ["no", copy.noAnnotation]]} copy={copy} />
      <Select label={copy.complexity} value={filters.complexity} onChange={setter(setFilters, "complexity")} options={[["beginner", copy.beginnerLevel], ["intermediate", copy.intermediate], ["advanced", copy.advanced]]} copy={copy} />
      <Select label={copy.possible} value={filters.output} onChange={setter(setFilters, "output")} options={Object.entries(OUTPUT_LABELS).map(([value, item]) => [value, localized(item, locale)])} copy={copy} />
    </div>{filtered.length ? <div className={styles.catalogGrid}>{filtered.map((item) => <ProjectCard key={item.id} project={item} locale={locale} copy={copy} onOpen={setSelectedId} />)}</div> : <p className={styles.empty}>{copy.none}</p>}</section>
    <aside className={styles.notice}>{copy.notice}</aside>
  </main>;
}

function SectionHeading({ number, title, lead, id }) { return <div className={styles.sectionHeading}><p className={styles.kicker}>{number} · {title}</p><h2 id={id}>{title}</h2><p>{lead}</p></div>; }
function Select({ label, value, onChange, options, copy }) { return <label className={styles.field}><span>{label}</span><select value={value} onChange={onChange}><option value="">{copy.any}</option>{options.map(([key, text]) => <option value={key} key={key}>{text}</option>)}</select></label>; }
function Info({ title, text }) { return <div><h4>{title}</h4><p>{text}</p></div>; }

function ChallengeExplorer({ activeId, onSelect, language, copy, onOpenProject }) {
  const challenge = CHALLENGE_BY_ID[activeId];
  const projects = challenge.possibleProjects.map((id) => PROJECT_CATALOG.find((item) => item.id === id)).filter(Boolean);
  return <section className={styles.section} aria-labelledby="arabic-challenges-title"><SectionHeading number="02" title={copy.challengesTitle} lead={copy.challengesLead} id="arabic-challenges-title" /><div className={styles.challengeTabs} role="tablist" aria-label={copy.challengesTitle}>{ARABIC_CHALLENGE_FAMILIES.map((item) => <button type="button" role="tab" aria-selected={activeId === item.id} key={item.id} onClick={() => onSelect(item.id)}>{language === "ar" ? item.titleAr : item.titleEn}</button>)}</div><article className={styles.challengePanel}><header><span>{copy.challenge}</span><h3>{language === "ar" ? challenge.titleAr : challenge.titleEn}</h3><p>{localized(challenge.description, language)}</p></header><div className={styles.challengeFacts}><Info title={copy.whyArabic} text={localized(challenge.whyItIsHardInArabic, language)} /><Info title={copy.researchQuestion} text={localized(challenge.commonResearchQuestions, language).join(" · ")} /><Info title={copy.requiredData} text={localized(challenge.dataNeeds, language)} /><Info title={copy.annotationLabel} text={localized(challenge.annotationNeeds, language)} /><Info title={copy.evaluation} text={localized(challenge.evaluationApproaches, language)} /><Info title={copy.application} text={localized(challenge.applicationPotential, language)} /></div><div className={styles.challengeConnections}><div><h4>{copy.use}</h4><div className={styles.badges}>{challenge.suitablePaths.map((pathId) => <Link href={PROJECT_PATH_ROUTES[pathId]} key={pathId}>{localized(PATH_GUIDANCE[pathId].name, language)}</Link>)}</div><div className={styles.badges}>{challenge.suitableTools.map((tool) => <Link href={PROJECT_TOOL_ROUTES[tool]} key={tool}>{tool}</Link>)}</div></div>{challenge.externalSteps.length > 0 && <aside className={styles.externalChallenge}><strong>{copy.external}</strong>{challenge.externalSteps.map((step) => <span key={localized(step, language)}>{localized(step, language)}</span>)}</aside>}</div><div className={styles.challengeProjects}><h4>{copy.suggestedProjects}</h4>{projects.map((project) => <button type="button" key={project.id} onClick={() => onOpenProject(project.id)}><span>{localized(project.title, language)}</span><small>{localized(project.expectedResults, language)}</small><span aria-hidden="true">→</span></button>)}</div></article></section>;
}

function SocialImpactExplorer({ filters, onFilter, language, copy, onOpenProject }) {
  const projects = filterSocialImpactProjects(filters);
  const flow = language === "ar" ? ["المشكلة المجتمعية", "الفئات المتأثرة", "المشكلة اللغوية", "مهمة NLP", "البيانات", "الترميز", "الطريقة", "التقييم", "تحليل الأخطاء", "النموذج الأولي", "الأثر المتوقع"] : ["Social problem", "Affected users", "Language problem", "NLP task", "Data", "Annotation", "Method", "Evaluation", "Error analysis", "Prototype", "Expected impact"];
  return <section className={`${styles.section} ${styles.socialSection}`} aria-labelledby="social-impact-title"><SectionHeading number="03" title={copy.socialTitle} lead={copy.socialLead} id="social-impact-title" /><p className={styles.socialPrinciple}>{copy.socialPrinciple}</p><ol className={styles.socialFlow}>{flow.map((step, index) => <li key={step}><span>{index + 1}</span>{step}</li>)}</ol><div className={styles.socialFilters} aria-label={copy.filters}><Select label={copy.chooseDomain} value={filters.domain} onChange={onFilter("domain")} options={SOCIAL_IMPACT_DOMAINS.map((item) => [item.id, language === "ar" ? item.titleAr : item.titleEn])} copy={copy} /><Select label={copy.possible} value={filters.form} onChange={onFilter("form")} options={Object.entries(OUTPUT_LABELS).map(([value, item]) => [value, localized(item, language)])} copy={copy} /><Select label={copy.teamLabel} value={filters.team} onChange={onFilter("team")} options={[["individual", copy.individual], ["team", copy.team]]} copy={copy} /><Select label={copy.annotationLabel} value={filters.annotation} onChange={onFilter("annotation")} options={[["yes", copy.needsAnnotation], ["no", copy.noAnnotation]]} copy={copy} /><Select label={copy.complexity} value={filters.complexity} onChange={onFilter("complexity")} options={[["beginner", copy.beginnerLevel], ["intermediate", copy.intermediate], ["advanced", copy.advanced]]} copy={copy} /></div><div className={styles.socialGrid}>{projects.map((project) => <SocialProjectCard key={project.id} project={project} language={language} copy={copy} onOpen={onOpenProject} />)}</div><div className={styles.problemMapping}><h3>{copy.mappingTitle}</h3>{SOCIAL_PROBLEM_MAPPINGS.map((item) => <div key={localized(item.problem, language)}><span>{localized(item.problem, language)}</span><b aria-hidden="true">→</b><strong>{item.task}</strong></div>)}</div><aside className={styles.ethicsNotice}>{copy.ethicsNotice}</aside></section>;
}

function SocialProjectCard({ project, language, copy, onOpen }) {
  const social = project.socialImpact;
  const domain = SOCIAL_IMPACT_DOMAINS.find((item) => item.id === social.domain);
  const level = project.complexity === "beginner" ? "beginnerLevel" : project.complexity;
  return <article className={styles.socialCard}><div className={styles.cardTop}><span className={styles.socialBadge}>{language === "ar" ? domain.titleAr : domain.titleEn}</span><span className={styles.levelBadge}>{copy[level]}</span></div><h3>{localized(project.title, language)}</h3><Info title={copy.socialProblem} text={localized(project.problem, language)} /><Info title={copy.affectedUsers} text={localized(social.affectedUsers, language)} /><Info title={copy.languageBarrier} text={localized(social.languageProblem, language)} /><div className={styles.badges}>{social.nlpTasks.map((task) => <span key={task}>{task}</span>)}</div><div className={styles.indicators}><span>{project.teamType === "team" ? copy.team : copy.individual}</span><span>{project.annotatorsRequired ? copy.needsAnnotation : copy.noAnnotation}</span><span>{copy.prototype}</span>{social.externalSteps.length > 0 && <span>{copy.externalBadge}</span>}</div><button type="button" className={styles.openButton} onClick={() => onOpen(project.id)}>{copy.open}<span aria-hidden="true">→</span></button></article>;
}

function AppliedProjectExplorer({ filters, onFilter, language, copy, onOpenProject }) {
  const entries = filterAppliedProjects(filters);
  const flow = language === "ar" ? ["القطاع", "الاحتياج التطبيقي", "المشكلة اللغوية", "مهمة NLP", "البيانات", "المسار والأداة", "التقييم", "تحليل الأخطاء", "التطبيق المحتمل", "القيمة المتوقعة"] : ["Sector", "Practical need", "Language problem", "NLP task", "Data", "Path / tool", "Evaluation", "Error analysis", "Potential application", "Expected value"];
  return <section className={`${styles.section} ${styles.appliedSection}`} aria-labelledby="applied-projects-title"><SectionHeading number="04" title={copy.appliedTitle} lead={copy.appliedLead} id="applied-projects-title" /><p className={styles.appliedPrinciple}>{copy.appliedPrinciple}</p><ol className={styles.socialFlow}>{flow.map((step, index) => <li key={step}><span>{index + 1}</span>{step}</li>)}</ol><div className={styles.socialFilters}><Select label={copy.sector} value={filters.sector} onChange={onFilter("sector")} options={APPLIED_SECTORS.map((item) => [item.id, language === "ar" ? item.titleAr : item.titleEn])} copy={copy} /><Select label={copy.possible} value={filters.form} onChange={onFilter("form")} options={Object.entries(OUTPUT_LABELS).map(([value, item]) => [value, localized(item, language)])} copy={copy} /><Select label={copy.teamLabel} value={filters.team} onChange={onFilter("team")} options={[["individual", copy.individual], ["team", copy.team]]} copy={copy} /><Select label={copy.annotationLabel} value={filters.annotation} onChange={onFilter("annotation")} options={[["yes", copy.needsAnnotation], ["no", copy.noAnnotation]]} copy={copy} /><Select label={copy.complexity} value={filters.complexity} onChange={onFilter("complexity")} options={[["beginner", copy.beginnerLevel], ["intermediate", copy.intermediate], ["advanced", copy.advanced]]} copy={copy} /></div><div className={styles.socialGrid}>{entries.map((entry) => <AppliedProjectCard key={entry.id} entry={entry} project={PROJECT_CATALOG.find((item) => item.id === entry.projectId)} language={language} copy={copy} onOpen={onOpenProject} />)}</div><aside className={styles.appliedNotice}>{copy.appliedNotice}</aside></section>;
}

function AppliedProjectCard({ entry, project, language, copy, onOpen }) {
  const sector = APPLIED_SECTORS.find((item) => item.id === entry.sector);
  const level = entry.complexity === "beginner" ? "beginnerLevel" : entry.complexity;
  return <article className={styles.appliedCard}><div className={styles.cardTop}><span className={styles.appliedBadge}>{copy.appliedBadge}</span><span className={styles.levelBadge}>{copy[level]}</span></div><small>{language === "ar" ? sector.titleAr : sector.titleEn}</small><h3>{language === "ar" ? entry.titleAr : entry.titleEn}</h3><Info title={copy.practicalNeed} text={language === "ar" ? entry.needAr : entry.needEn} /><Info title={copy.languageBarrier} text={localized(entry.languageProblem, language)} /><div className={styles.badges}>{entry.nlpTasks.map((task) => <span key={task}>{task}</span>)}</div><div className={styles.badges}>{entry.relatedArabicChallenges.map((id) => <span key={id}>{language === "ar" ? CHALLENGE_BY_ID[id]?.titleAr : CHALLENGE_BY_ID[id]?.titleEn}</span>)}</div><div className={styles.indicators}><span>{entry.individualOrTeam === "team" ? copy.team : copy.individual}</span><span>{entry.needsAnnotators ? copy.needsAnnotation : copy.noAnnotation}</span><span>{copy.prototype}</span>{entry.externalSteps.length > 0 && <span>{copy.externalBadge}</span>}</div><button type="button" className={styles.openButton} onClick={() => onOpen(project.id)}>{copy.open}<span aria-hidden="true">→</span></button></article>;
}

function ProjectCard({ project, locale, copy, onOpen, compact = false }) {
  const level = project.complexity === "beginner" ? "beginnerLevel" : project.complexity;
  return <article className={`${styles.projectCard} ${compact ? styles.compact : ""}`}><div className={styles.cardTop}><Link className={styles.pathBadge} href={PROJECT_PATH_ROUTES[project.path]}>{localized(PATH_GUIDANCE[project.path].name, locale)}</Link><span className={styles.levelBadge}>{copy[level]}</span></div><h3>{localized(project.title, locale)}</h3><p>{localized(project.problem, locale)}</p>{!compact && <><dl><div><dt>{copy.impact}</dt><dd>{localized(project.impact, locale)}</dd></div><div><dt>{copy.requiredData}</dt><dd>{localized(project.dataRequirements, locale)}</dd></div><div><dt>{copy.coreSteps}</dt><dd>{localized(project.steps, locale).join(" → ")}</dd></div><div><dt>{copy.expected}</dt><dd>{localized(project.expectedResults, locale)}</dd></div><div><dt>{copy.evaluation}</dt><dd>{localized(project.evaluation, locale)}</dd></div></dl><div className={styles.badges}>{project.tools.map((tool) => <Link href={PROJECT_TOOL_ROUTES[tool]} key={tool}>{tool}</Link>)}</div><div className={styles.outputGrid}>{project.possibleOutputs.map((output) => <span key={output}>{localized(OUTPUT_LABELS[output], locale)}</span>)}</div></>}<ProjectQuickLinks project={project} copy={copy} /><div className={styles.indicators}><span>{project.teamType === "team" ? copy.team : copy.individual}</span><span>{project.annotatorsRequired ? copy.needsAnnotation : copy.noAnnotation}</span></div><button type="button" className={styles.openButton} onClick={() => onOpen(project.id)}>{copy.open}<span aria-hidden="true">→</span></button></article>;
}

function ProjectQuickLinks({ project, copy }) {
  const roadmap = buildProjectRoadmap(project);
  const links = [["path", copy.pathLink], ["data", copy.dataLink], ["tool", copy.toolLink], ["report", copy.reportLink], ["writing", copy.writingLink]];
  return <nav className={styles.quickLinks} aria-label={copy.execute}>{links.map(([stage, label]) => { const step = roadmap.find((item) => item.stage === stage); return <Link key={stage} href={step.href}>{label}</Link>; })}</nav>;
}

function ProjectDetail({ project, language, copy, onBack }) {
  const path = PATH_GUIDANCE[project.path];
  const challenge = project.challengeId ? CHALLENGE_BY_ID[project.challengeId] : ARABIC_CHALLENGE_FAMILIES.find((item) => item.possibleProjects.includes(project.id));
  const roadmap = buildProjectRoadmap(project);
  const guides = getProjectGuides(project);
  const prototype = getPrototypeProfile(project.id);
  const applied = APPLIED_PROJECT_BY_PROJECT_ID[project.id];
  const handoffFields = getPrototypeHandoffFields(project);
  const [handoffOpen, setHandoffOpen] = useState(false);
  const [researcherEdits, setResearcherEdits] = useState({});
  const [contextReviewed, setContextReviewed] = useState(false);
  const [missingFields, setMissingFields] = useState([]);
  const [aiGuidance, setAiGuidance] = useState(null);
  const [guidanceStatus, setGuidanceStatus] = useState("idle");
  const handoff = prototype ? buildPrototypeHandoff(project, language, researcherEdits) : null;
  function openPrototypeHandoff() {
    setHandoffOpen(true);
    requestAnimationFrame(() => document.getElementById("prototype-builder")?.scrollIntoView({ behavior: "smooth", block: "start" }));
  }
  function updateContext(field, value) {
    setResearcherEdits((current) => ({ ...current, [field]: value }));
    setContextReviewed(false);
    setAiGuidance(null);
    setGuidanceStatus("idle");
  }
  function reviewContext() {
    const current = buildPrototypeHandoff(project, language, researcherEdits);
    setMissingFields(current.missing);
    setContextReviewed(current.missing.length === 0);
  }
  async function requestGuidance() {
    const current = buildPrototypeHandoff(project, language, researcherEdits);
    if (!contextReviewed || current.missing.length) {
      setMissingFields(current.missing);
      return;
    }
    setGuidanceStatus("loading");
    try {
      const response = await fetch("/api/project-prototype-guidance", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ projectId: project.id, uiLanguage: language, researcherEdits: current.researcherEdits }) });
      const payload = await response.json();
      if (!response.ok || !payload.guidance) throw new Error(payload.error || "Guidance failed");
      setAiGuidance(payload.guidance);
      setGuidanceStatus("ready");
    } catch {
      setGuidanceStatus("error");
    }
  }
  return <main className={styles.page}><Head><title>{localized(project.title, language)} | LinguaLab</title></Head><div className={styles.detailNav}><button type="button" onClick={onBack}>← {copy.back}</button><Link href="/">LinguaLab</Link></div><article className={styles.detail}>
    <header className={styles.detailHero}><span className={styles.pathBadge}>{localized(path.name, language)}</span><p className={styles.eyebrow}>{copy.open}</p><h1>{localized(project.title, language)}</h1><p>{localized(project.impact, language)}</p></header>
    {project.socialImpact && <SocialImpactDetail project={project} language={language} copy={copy} />}
    {applied && <AppliedContextDetail applied={applied} language={language} copy={copy} />}
    {challenge && <DetailSection title={copy.challenge}><div className={styles.challengeDetail}><div><span className={styles.challengeBadge}>{language === "ar" ? challenge.titleAr : challenge.titleEn}</span><h3>{copy.whyArabic}</h3><p>{localized(challenge.whyItIsHardInArabic, language)}</p></div><div><h3>{copy.use}</h3><p>{localized(path.name, language)} · {project.tools.join(" · ")}</p><h3>{copy.contribution}</h3><p>{localized(project.impact, language)}</p></div>{project.externalSteps?.length > 0 && <aside className={styles.externalChallenge}><strong>{copy.external}</strong>{project.externalSteps.map((step) => <span key={localized(step, language)}>{localized(step, language)}</span>)}</aside>}</div></DetailSection>}
    <DetailSection letter="A" title={copy.why}><div className={styles.detailGrid}><DetailCard title={copy.problem} text={localized(project.problem, language)} /><DetailCard title={copy.impact} text={localized(project.impact, language)} /><DetailCard title={copy.possible} text={localized(project.applicationPotential, language)} /></div></DetailSection>
    <DetailSection letter="B" title={copy.before}><div className={styles.detailGrid}><DetailCard title={copy.requiredData} text={localized(project.dataRequirements, language)} /><DetailCard title={copy.sample} text={copy.sampleText} /><DetailCard title={copy.teamLabel} text={project.teamType === "team" ? copy.team : copy.individual} /><DetailCard title={copy.annotationLabel} text={localized(project.annotationNotes, language)} /></div></DetailSection>
    <DetailSection letter="C" title={copy.use}><Link className={styles.canonicalPath} href={PROJECT_PATH_ROUTES[project.path]}>{localized(path.name, language)}<span aria-hidden="true">↗</span></Link><div className={styles.toolLinks}>{project.tools.map((tool) => <Link key={tool} href={PROJECT_TOOL_ROUTES[tool]}>{tool}<span aria-hidden="true">↗</span></Link>)}</div></DetailSection>
    <DetailSection letter="D" title={copy.execute}><ol className={styles.roadmap}>{roadmap.map((step, index) => <li className={step.external ? styles.externalStep : styles.internalStep} key={`${step.stage}-${index}`}><span className={styles.stepNumber}>{String(index + 1).padStart(2, "0")}</span><div><small>{step.external ? copy.external : step.stage}</small>{step.href ? <Link href={step.href}>{localized(step.label, language)}<span aria-hidden="true">↗</span></Link> : <strong>{localized(step.label, language)}</strong>}<p>{localized(step.note, language)}</p></div></li>)}</ol></DetailSection>
    <DetailSection letter="E" title={copy.results}><div className={styles.resultLayers}><DetailCard title={copy.measured} text={localized(project.expectedResults, language)} /><DetailCard title={copy.ai} text={language === "ar" ? "قد يساعد AI في تفسير الأنماط والأخطاء، لكنه لا يغير النتائج المقاسة ولا المرجع البشري." : "AI may help interpret patterns and errors, but it does not alter measured results or the human reference."} /><DetailCard title={copy.researcher} text={language === "ar" ? "يقرر الباحث ما يمكن اعتماده ويبرر الاستنتاجات في ضوء المنهج والقيود." : "The researcher decides what can be accepted and justifies conclusions against the method and limitations."} /></div></DetailSection>
    <DetailSection letter="F" title={copy.success}><p>{localized(project.evaluation, language)}</p></DetailSection>
    <DetailSection letter="G" title={copy.possible}><div className={styles.outputGrid}>{project.possibleOutputs.map((output) => <span key={output}>{localized(OUTPUT_LABELS[output], language)}</span>)}</div>{prototype && <button type="button" className={styles.handoffButton} onClick={openPrototypeHandoff}>{copy.handoffAction}<span aria-hidden="true">→</span></button>}</DetailSection>
    <DetailSection letter="H" title={copy.guides}><p>{copy.guidesLead}</p><div className={styles.guideDetails}>{guides.map((item) => <details key={item.id}><summary><span>{localized(item.title, language)}</span><small>{copy.textGuide}</small></summary><div className={styles.guideBody}>{[[copy.guideWhat, item.what], [copy.guideWhy, item.why], [copy.guidePrepare, item.prepare], [copy.guideInside, item.inside], [copy.guideInspect, item.inspect], [copy.guideWarnings, item.warnings], [copy.guideNext, item.next]].map(([label, value]) => <Info key={label} title={label} text={localized(value, language)} />)}</div></details>)}</div></DetailSection>
    {prototype && <section id="prototype-builder" className={styles.prototypeSection}><h2>I. {copy.buildAi}</h2><p>{copy.buildLead}</p><aside className={styles.aiNotice}><strong>{copy.aiGuidance}</strong><p>{copy.engineeringNotice}</p></aside>{handoffOpen ? <><PrototypeContextEditor handoff={handoff} fields={handoffFields} language={language} copy={copy} missingFields={missingFields} onChange={updateContext} /><button className={styles.reviewButton} type="button" onClick={reviewContext}>{copy.reviewContext}</button>{contextReviewed && <p className={styles.contextReady}>{copy.contextReady}</p>}<PrototypeTimeline project={project} language={language} copy={copy} /><nav className={styles.prototypeLinks} aria-label={copy.prototypeLinks}>{getPrototypeLinks(project).map((item) => <Link href={item.href} key={item.id}>{localized(item.label, language)}<span aria-hidden="true">↗</span></Link>)}</nav><button className={styles.guidanceButton} type="button" onClick={requestGuidance} disabled={!contextReviewed || guidanceStatus === "loading"}>{guidanceStatus === "loading" ? copy.generating : copy.generateGuidance}</button>{guidanceStatus === "error" && <p role="alert" className={styles.guidanceError}>{copy.guidanceError}</p>}{aiGuidance && <PrototypeGuidance guidance={aiGuidance} copy={copy} />}</> : <button type="button" className={styles.handoffButton} onClick={openPrototypeHandoff}>{copy.handoffAction}<span aria-hidden="true">→</span></button>}<aside className={styles.starterNotice}>{copy.starterNotice}</aside><aside className={styles.licenseNotice}>{copy.rightsNotice}</aside></section>}
    <aside className={styles.outside}><strong>{copy.outside}</strong><p>{copy.outsideText}</p></aside><aside className={styles.notice}>{copy.notice}</aside>
  </article></main>;
}

function AppliedContextDetail({ applied, language, copy }) {
  const sector = APPLIED_SECTORS.find((item) => item.id === applied.sector);
  return <DetailSection title={copy.appliedContext}><div className={styles.appliedDetail}><div className={styles.appliedDetailLead}><span className={styles.appliedBadge}>{copy.appliedBadge}</span><h3>{copy.sector}</h3><p>{language === "ar" ? sector.titleAr : sector.titleEn}</p></div><Info title={copy.practicalNeed} text={language === "ar" ? applied.needAr : applied.needEn} /><Info title={copy.languageBarrier} text={localized(applied.languageProblem, language)} /><Info title={copy.whyNlp} text={localized(applied.whyItMatters, language)} /><Info title={copy.possibleApplication} text={localized(applied.possibleApplication, language)} /><Info title={copy.practicalValue} text={localized(applied.expectedPracticalValue, language)} /><Info title={copy.risks} text={localized(applied.limitations, language)} /><Info title={copy.licensing} text={`${localized(applied.privacyConsiderations, language)} ${localized(applied.legalOrLicensingNotes, language)}`} /></div>{applied.externalSteps.length > 0 && <aside className={styles.externalChallenge}><strong>{copy.external}</strong>{applied.externalSteps.map((step) => <span key={localized(step, language)}>{localized(step, language)}</span>)}</aside>}<aside className={styles.appliedNotice}>{copy.appliedNotice}</aside></DetailSection>;
}

function SocialImpactDetail({ project, language, copy }) {
  const social = project.socialImpact;
  const domain = SOCIAL_IMPACT_DOMAINS.find((item) => item.id === social.domain);
  return <DetailSection title={copy.socialTitle}><div className={styles.socialDetail}><div className={styles.socialDetailLead}><span className={styles.socialBadge}>{language === "ar" ? domain.titleAr : domain.titleEn}</span><h3>{copy.socialProblem}</h3><p>{localized(project.problem, language)}</p></div><Info title={copy.affectedUsers} text={localized(social.affectedUsers, language)} /><Info title={copy.languageBarrier} text={localized(social.languageProblem, language)} /><Info title={copy.whyNlp} text={localized(social.whyItMatters, language)} /><Info title={copy.socialBenefit} text={localized(social.expectedSocialImpact, language)} /><Info title={copy.risks} text={localized(social.risksAndLimitations, language)} /><Info title={copy.privacy} text={localized(social.privacyConsiderations, language)} /></div>{project.challengeIds?.length > 0 && <div className={styles.challengeLinks}>{project.challengeIds.map((id) => { const challenge = CHALLENGE_BY_ID[id]; return challenge ? <span key={id}>{language === "ar" ? challenge.titleAr : challenge.titleEn}</span> : null; })}</div>}{social.externalSteps.length > 0 && <aside className={styles.externalChallenge}><strong>{copy.external}</strong>{social.externalSteps.map((step) => <span key={localized(step, language)}>{localized(step, language)}</span>)}</aside>}{social.domain === "health" && <aside className={styles.healthNotice}>{copy.healthNotice}</aside>}<aside className={styles.ethicsNotice}>{copy.ethicsNotice}</aside></DetailSection>;
}
function DetailSection({ letter, title, children }) { return <section><h2>{letter ? `${letter}. ` : ""}{title}</h2>{children}</section>; }
function DetailCard({ title, text }) { return <div className={styles.detailCard}><h3>{title}</h3><p>{text}</p></div>; }

function PrototypeContextEditor({ handoff, fields, language, copy, missingFields, onChange }) {
  return <div className={styles.contextReview}><header><h3>{copy.inheritedTitle}</h3><p>{copy.inheritedLead}</p></header><div className={styles.contextFields}>{fields.map((field) => { const missing = missingFields.includes(field.id); return <div className={`${styles.contextField} ${missing ? styles.missingField : ""}`} key={field.id}><div><strong>{localized(field.label, language)}</strong><p>{handoff.inherited[field.id] || "—"}</p></div><label><span>{copy.editsTitle}</span><textarea value={handoff.researcherEdits[field.id]} onChange={(event) => onChange(field.id, event.target.value)} placeholder={copy.editsHelp} rows={2} />{missing && <small>{copy.missingContext} {localized(field.label, language)}</small>}</label></div>; })}</div></div>;
}

function PrototypeTimeline({ project, language, copy }) {
  const labels = { problem: copy.problem, solution: language === "ar" ? "الحل المقترح" : "Proposed solution", inputs: copy.inputs, outputs: copy.expected, data: copy.requiredData, method: copy.method, logic: language === "ar" ? "منطق النموذج" : "Prototype logic", test: copy.test, evaluate: copy.evaluation, improve: copy.improve };
  return <div><h3 className={styles.subheading}>{copy.prototypeFlow}</h3><ol className={styles.prototypeTimeline}>{buildPrototypeRoadmap(project).map((step, index) => <li key={step.stage}><span>{index + 1}</span><div><strong>{labels[step.stage]}</strong>{step.href ? <Link href={step.href}>{localized(step.label, language)} ↗</Link> : <p>{localized(step.label, language)}</p>}</div></li>)}</ol></div>;
}

function PrototypeGuidance({ guidance, copy }) {
  const blocks = [[copy.purpose, guidance.purpose], [copy.intendedUsers, guidance.intendedUsers], [copy.inputs, guidance.inputs], [copy.expected, guidance.outputs], [copy.method, guidance.method], [copy.processing, guidance.processingFlow], [copy.architecture, guidance.architecture], [copy.pseudocode, guidance.pseudocode], [copy.starter, guidance.starterCodeDirection], [copy.testing, guidance.testing], [copy.evaluation, guidance.evaluation], [copy.improvement, guidance.improvement], [copy.guideWarnings, guidance.caution]];
  return <div className={styles.generatedGuidance} aria-live="polite"><h3>{copy.aiGuidance}</h3><div>{blocks.map(([label, value]) => <article key={label}><h4>{label}</h4>{Array.isArray(value) ? <ol>{value.map((item) => <li key={item}>{item}</li>)}</ol> : <p>{value}</p>}</article>)}</div></div>;
}
